package dev.thisolivier.timeconverter.core.fixtures

import kotlinx.serialization.Serializable

/**
 * The schema of `fixtures/world-clock-cases.json` (items 30/32), generated by
 * the Swift core. Field for field the Swift `SharedWorldClockFixtureModels.swift`;
 * change both together.
 */
@Serializable
data class WorldClockCaseFile(
    val schemaVersion: Int,
    val generatedBy: String,
    val cases: List<WorldClockCase>,
)

@Serializable
data class WorldClockCase(
    val id: String,
    val note: String? = null,
    /** ISO-8601 instant injected as "now". */
    val now: String,
    /** IANA identifier injected as the device zone. */
    val localZone: String,
    /** Always a whole number of minutes. */
    val offsetSeconds: Int,
    val favourites: List<WorldClockFixtureFavourite>,
    val expected: ExpectedWorldClock,
)

/** A `FavouriteDestination`, spelled out field by field. */
@Serializable
data class WorldClockFixtureFavourite(
    val timeZoneIdentifier: String,
    /** `place` or `code`. */
    val labelKind: String,
    val name: String? = null,
    val code: String? = null,
    val expandedName: String? = null,
)

@Serializable
data class ExpectedWorldClock(
    val readout: String,
    val offsetDescription: String? = null,
    val rows: List<ExpectedWorldClockRow>,
)

@Serializable
data class ExpectedWorldClockRow(
    val isLocal: Boolean,
    val placeName: String,
    val clockDigits: String,
    val meridiem: String,
    val zoneLine: String,
    val offsetPhrase: String,
)
